import{_ as a,o as i,c as t,ag as r}from"./chunks/framework.DCKC-kU_.js";const m=JSON.parse('{"title":"Versioning and compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"spec/versioning.md","filePath":"spec/versioning.md"}'),o={name:"spec/versioning.md"};function n(s,e,d,c,l,p){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="versioning-and-compatibility" tabindex="-1">Versioning and compatibility <a class="header-anchor" href="#versioning-and-compatibility" aria-label="Permalink to &quot;Versioning and compatibility&quot;">​</a></h1><p>Takoform versions protocol, Forms, packages, and the Terraform/OpenTofu provider for different reasons. Their numbers MUST NOT be aligned to imply a shared release or maturity level. Form maturity and the complete lifecycle are defined in <a href="./project-lifecycle.html"><code>project-lifecycle.md</code></a>.</p><h2 id="version-axes" tabindex="-1">Version axes <a class="header-anchor" href="#version-axes" aria-label="Permalink to &quot;Version axes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Identifier</th><th>Meaning</th></tr></thead><tbody><tr><td>Host API</td><td>API group such as current <code>forms.takoform.com/v1alpha2</code></td><td>Protocol envelope, discovery, and lifecycle compatibility</td></tr><tr><td>Form epoch</td><td>API group inside an exact <code>FormRef</code></td><td>Namespace boundary between frozen v1alpha1 Legacy Forms and current v1alpha2 Forms</td></tr><tr><td>Form</td><td>SemVer inside an exact <code>FormRef</code></td><td>Compatibility of one portable desired-state contract within its epoch</td></tr><tr><td>Form Package</td><td>Exact package identity plus content digest</td><td>Immutable distribution of one exact Form and its fixtures</td></tr><tr><td>Provider</td><td>Provider SemVer</td><td>Terraform/OpenTofu protocol, typed surface, persisted state, and host-client compatibility</td></tr></tbody></table><p>Host Support, Form Activation, and Service Offering records refer to exact identities but are not version streams. Updating one of those facts MUST NOT change a Form or provider version.</p><p>Current <code>packages.forms.takoform.com/v1alpha3</code> packages have no independent SemVer. Their exact package digest produces the publication artifact ID <code>sha256-&lt;hex&gt;</code> and therefore the source path and tag. Existing v1alpha1 <code>packageVersion</code> values and the published content-addressed v1alpha2 package profile remain immutable Legacy identities; tooling MUST preserve and verify their paths, tags, signatures, and bytes without interpreting a package profile as Form maturity. The content-addressed locator decision is recorded in <a href="./decisions/0005-current-form-packages-use-content-addressed-locators.html"><code>decisions/0005</code></a>, and the v1alpha3 envelope required by the Form epoch reset is recorded in <a href="./decisions/0006-v1alpha2-restarts-form-lines.html"><code>decisions/0006</code></a>.</p><h2 id="provider-versions-are-independent" tabindex="-1">Provider versions are independent <a class="header-anchor" href="#provider-versions-are-independent" aria-label="Permalink to &quot;Provider versions are independent&quot;">​</a></h2><p>A provider release version describes only:</p><ul><li>Terraform/OpenTofu protocol compatibility;</li><li>resource and data-source schema compatibility;</li><li>persisted provider state and state-upgrade behavior;</li><li>host API client behavior and supported protocol capabilities.</li></ul><p>It does not describe Form maturity, package publication order, Host Support, Form Activation, a Service Offering, or a historical admission generation.</p><p>Within a stable provider major, a release MUST NOT remove an existing resource type, make an existing valid configuration invalid, silently reinterpret persisted state as a different FormRef, or discard a supported state migration. Such a change requires a new provider major. Compatible optional fields, new resource types, expanded exact-Form compatibility, and bug fixes MAY remain in the current major when they preserve those promises.</p><p>A provider release MAY support a mixed set of Form versions and maturity states. Changing the provider major MUST NOT reset, renumber, promote, or deprecate a Form. Changing a Form MUST NOT require a provider release when the provider can already carry that Form&#39;s data and exact identity correctly.</p><p>The provider compatibility decision is recorded in <a href="./decisions/0001-provider-v1-keeps-form-versions-independent.html"><code>decisions/0001-provider-v1-keeps-form-versions-independent.md</code></a>. Current provider release facts belong to <a href="./../release/"><code>../release/</code></a>, not this compatibility policy.</p><h2 id="form-versions" tabindex="-1">Form versions <a class="header-anchor" href="#form-versions" aria-label="Permalink to &quot;Form versions&quot;">​</a></h2><h3 id="proposal" tabindex="-1">Proposal <a class="header-anchor" href="#proposal" aria-label="Permalink to &quot;Proposal&quot;">​</a></h3><p>A Form Proposal has no public version. Proposal edits MAY be breaking and a Proposal MAY be withdrawn without reserving a FormRef.</p><h3 id="experimental-0-x" tabindex="-1">Experimental <code>0.x</code> <a class="header-anchor" href="#experimental-0-x" aria-label="Permalink to &quot;Experimental `0.x`&quot;">​</a></h3><p>The first reproducible public version of a new Form line is <code>0.1.0</code>.</p><ul><li>A breaking semantic or schema change increments the minor version and resets the patch version.</li><li>A compatible addition increments the minor version.</li><li>A compatible correction that does not change the accepted desired contract increments the patch version.</li></ul><p>Every released <code>0.x</code> identity remains immutable. Experimental means the next release may break according to this policy; it never permits overwriting the current release.</p><h3 id="stable-1-x" tabindex="-1">Stable <code>1.x+</code> <a class="header-anchor" href="#stable-1-x" aria-label="Permalink to &quot;Stable `1.x+`&quot;">​</a></h3><p>A Form MAY begin a stable major only after satisfying the Stable criteria in <a href="./project-lifecycle.html"><code>project-lifecycle.md</code></a>. The initial earned stable line begins at <code>1.0.0</code> for a new kind.</p><ul><li>A patch MUST preserve the desired schema and portable semantics. It MAY fix documentation, fixtures, or non-semantic metadata only when the package identity changes without rewriting prior bytes.</li><li>A minor MAY add optional data or relax a constraint. Every previously valid desired document MUST remain valid with the same portable meaning.</li><li>A major MAY remove data, tighten a constraint, change meaning, or require replacement or explicit state migration.</li></ul><p>Schema compatibility checks are conservative. When tooling cannot prove that a change is compatible, the change MUST be treated as breaking or remain a Proposal until the proof is improved.</p><h3 id="existing-identities" tabindex="-1">Existing identities <a class="header-anchor" href="#existing-identities" aria-label="Permalink to &quot;Existing identities&quot;">​</a></h3><p>An occupied FormRef MUST never be reused for different bytes. An existing kind whose public version is already <code>1.x</code> or later MUST NOT be renumbered to <code>0.x</code> or presented as Stable merely because its number is greater than zero.</p><p>The Forms and admission documents published before decision <a href="./decisions/0004-takoform-is-an-experimental-specification.html"><code>0004</code></a> are a Legacy line. Their original version numbers and document fields remain intact; current lifecycle projections describe them as Legacy without changing the published definitions.</p><h2 id="form-and-package-identity" tabindex="-1">Form and package identity <a class="header-anchor" href="#form-and-package-identity" aria-label="Permalink to &quot;Form and package identity&quot;">​</a></h2><p>A Form&#39;s identity is its exact <code>FormRef</code>. The <code>schemaDigest</code> binds the canonical Form Definition bytes. Two definitions with different canonical bytes are different identities even if their display names match.</p><p>A package binds one exact FormRef to a closed byte inventory, fixtures, metadata, provenance, and digest. Published package bytes MUST NOT be changed, re-signed as a replacement, or served under an occupied identity.</p><p>Changing only package metadata or fixtures does not by itself change Form maturity. Different closed package bytes produce a different package digest and therefore a different current publication locator. They do not require a new Form SemVer unless the Form contract itself changed.</p><h2 id="host-api-group" tabindex="-1">Host API group <a class="header-anchor" href="#host-api-group" aria-label="Permalink to &quot;Host API group&quot;">​</a></h2><p>The current Host API wire <code>forms.takoform.com/v1alpha2</code> remains Experimental and carries only exact v1alpha2 FormRefs. The frozen <code>forms.takoform.com/v1alpha1</code> Host API and Form epoch remain a closed provider-v1 compatibility lane. Current discovery is <code>/.well-known/takoform/v1alpha2</code>; frozen Legacy discovery remains <code>/.well-known/takoform</code>. Each lane has its own discovery path and API base; a Host wire version never implies Form maturity. Breaking protocol changes require a new Host API group identity.</p><p>The API group MUST NOT graduate based on a Form count, package publication, provider major, historical admission, or one host&#39;s conformance report. A future graduation decision requires, at minimum:</p><ol><li>two independently operated hosts exercising the same lifecycle semantics;</li><li>a documented compatibility window with no breaking operation change;</li><li>end-to-end materialization of each retained optional interface surface;</li><li>cross-publisher package installation and lifecycle evidence;</li><li>a real deprecation/removal exercise and production consumption of the revocation chain.</li></ol><p>Any graduation is a separate ADR and public migration plan. Until then, the project and API MUST NOT be described as stable.</p><h2 id="deprecation-legacy-and-revocation" tabindex="-1">Deprecation, Legacy, and revocation <a class="header-anchor" href="#deprecation-legacy-and-revocation" aria-label="Permalink to &quot;Deprecation, Legacy, and revocation&quot;">​</a></h2><p>Deprecation announces a migration contract; Legacy is the retained lifecycle state after the current line is no longer recommended for new work. Neither operation deletes public bytes.</p><p>Security revocation is separate, append-only, and described in <a href="./trust/"><code>trust/</code></a>. It may block new creation, update, or activation while retaining the referenced bytes for safe observation, deletion, recovery, or an explicit operator evacuation path.</p>',39)])])}const u=a(o,[["render",n]]);export{m as __pageData,u as default};
